import json,collections
def majority(A,k):
    H,W=len(A),len(A[0]); out=[[0]*(W//k) for _ in range(H//k)]
    for i in range(H//k):
        for j in range(W//k):
            cnt=collections.Counter()
            for y in range(i*k,i*k+k):
                for x in range(j*k,j*k+k):
                    v=A[y][x]
                    if v not in(0,5): cnt[v]+=1
            if cnt: out[i][j]=cnt.most_common(1)[0][0]
    return out
